    function _atomicPreflightHash(bytes32 grantDigest, ReservationV1[] calldata reservations)
        private
        view
        returns (bytes32 readbackHash)
    {
        _requireRuntime(_PREFLIGHT, _PREFLIGHT_RUNTIME_CODEHASH);
        bytes memory payload = abi.encodeCall(
            IProgrammableUniversalLaunchPreflightV1.atomicPreflightHashV1,
            (address(this), address(this).codehash, grantDigest, reservations)
        );
        bool success;
        uint256 returnedSize;
        address preflight = _PREFLIGHT;
        assembly ("memory-safe") {
            success := staticcall(500000, preflight, add(payload, 32), mload(payload), 0, 0)
            returnedSize := returndatasize()
            if and(success, eq(returnedSize, 32)) {
                returndatacopy(0, 0, 32)
                readbackHash := mload(0)
            }
        }
        if (!success || returnedSize != 32 || readbackHash == bytes32(0)) revert InvalidState();
        _requireRuntime(_PREFLIGHT, _PREFLIGHT_RUNTIME_CODEHASH);
    }

    function _reserveAll(bytes32 grantDigest, ReservationV1[] calldata reservations) private returns (bytes32 setHash) {
        uint256 length = reservations.length;
        if (length == 0 || length > MAX_RESERVATIONS) revert InvalidField(7);
        for (uint256 i; i < length; ++i) {
            ReservationV1 calldata reservation = reservations[i];
            bytes32 key = _reservationKey(reservation);
            for (uint256 j; j < i; ++j) {
                if (_reservationKey(reservations[j]) == key) revert InvalidField(8);
            }
            if (reservation.scope == ReservationScope.Exclusive) {
                if (reservation.sharedIdentityHash != bytes32(0) || _exclusiveReservation[key] != bytes32(0)) {
                    revert Replay();
                }
                _exclusiveReservation[key] = grantDigest;
            } else if (reservation.scope == ReservationScope.SharedInfrastructure) {
                if (reservation.sharedIdentityHash == bytes32(0) || _exclusiveReservation[key] != bytes32(0)) {
                    revert InvalidField(9);
                }
                bytes32 priorIdentity = _sharedReservationIdentity[key];
                if (priorIdentity != bytes32(0) && priorIdentity != reservation.sharedIdentityHash) revert Replay();
                _sharedReservationIdentity[key] = reservation.sharedIdentityHash;
            } else {
                revert InvalidField(10);
            }
            bytes32 leaf = keccak256(
                abi.encode(
                    RESERVATION_LEAF_TYPEHASH,
                    key,
                    uint8(reservation.scope),
                    reservation.expectedRuntimeCodeHash,
                    reservation.expectedManagerRuntimeCodeHash,
                    reservation.sharedIdentityHash
                )
            );
            setHash = keccak256(abi.encode(setHash, i, leaf));
        }
    }

    function _reservationSetHash(ReservationV1[] calldata reservations) private view returns (bytes32 setHash) {
        uint256 length = reservations.length;
        if (length == 0 || length > MAX_RESERVATIONS) revert InvalidField(11);
        for (uint256 i; i < length; ++i) {
            ReservationV1 calldata reservation = reservations[i];
            bytes32 leaf = keccak256(
                abi.encode(
                    RESERVATION_LEAF_TYPEHASH,
                    _reservationKey(reservation),
                    uint8(reservation.scope),
                    reservation.expectedRuntimeCodeHash,
                    reservation.expectedManagerRuntimeCodeHash,
                    reservation.sharedIdentityHash
                )
            );
            setHash = keccak256(abi.encode(setHash, i, leaf));
        }
    }

    function _reservationKey(ReservationV1 calldata reservation) private view returns (bytes32) {
        if (reservation.kind == ReservationKind.None || reservation.scope == ReservationScope.None) {
            revert InvalidField(12);
        }
        if (reservation.kind == ReservationKind.Pool) {
            if (
                reservation.account != address(0) || reservation.manager == address(0)
                    || reservation.identifier == bytes32(0) || reservation.expectedRuntimeCodeHash != bytes32(0)
                    || reservation.expectedManagerRuntimeCodeHash == bytes32(0)
            ) {
                revert InvalidField(13);
            }
        } else if (
            reservation.account == address(0) || reservation.manager != address(0)
                || reservation.identifier != bytes32(0) || reservation.expectedRuntimeCodeHash == bytes32(0)
                || reservation.expectedManagerRuntimeCodeHash != bytes32(0)
        ) {
            revert InvalidField(14);
        }
        return keccak256(
            abi.encode(
                RESERVATION_KEY_TYPEHASH,
                block.chainid,
                address(this),
                uint8(reservation.kind),
                reservation.account,
                reservation.manager,
                reservation.identifier
            )
        );
    }

    function _hashTypedData(bytes32 structHash) private view returns (bytes32) {
        return keccak256(abi.encodePacked(hex"1901", DOMAIN_SEPARATOR, structHash));
    }

    function _nextGrantStateHead(LaunchGrantStateHeadV1 storage head, LaunchGrantStatus next)
        private
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(GRANT_STATE_HEAD_TYPEHASH, uint8(next), head.grantHash, head.winnerKeyHash, head.stateHeadHash)
        );
    }

    function _requireProfileCurrent(ProfileDescriptorV1 storage descriptor) private view {
        if (descriptor.status != ProfileStatus.Active) revert ProfileUnavailable();
        if (_control.globalKilled) revert GlobalKillActive();
        _requireRuntime(descriptor.module, descriptor.moduleRuntimeCodeHash);
        _requireRuntimeBinding(descriptor.module, descriptor.moduleRuntimeCodeHash, descriptor.providerBindingHash);
        _requireControlEquality(descriptor);
    }

    function _requireRuntimeBinding(
        address account,
        bytes32 expectedRuntimeCodeHash,
        bytes32 expectedRuntimeBindingHash
    ) private view {
        _requireRuntime(account, expectedRuntimeCodeHash);
        bytes memory payload = abi.encodeCall(IProgrammableRuntimeBindingV1.runtimeBindingHashV1, ());
        bool success;
        uint256 returnedSize;
        bytes32 actualRuntimeBindingHash;
        assembly ("memory-safe") {
            success := staticcall(100000, account, add(payload, 32), mload(payload), 0, 0)
            returnedSize := returndatasize()
            if and(success, eq(returnedSize, 32)) {
                returndatacopy(0, 0, 32)
                actualRuntimeBindingHash := mload(0)
            }
        }
        if (!success || returnedSize != 32 || actualRuntimeBindingHash != expectedRuntimeBindingHash) {
            revert InvalidState();
        }
        _requireRuntime(account, expectedRuntimeCodeHash);
    }

    function _requireClosedRuntimeBinding(
        address account,
        bytes32 expectedRuntimeCodeHash,
        bytes32 expectedRuntimeBindingHash,
        bool requireStateless
    ) private view returns (bytes32 attestationHash) {
        _requireRuntime(_PREFLIGHT, _PREFLIGHT_RUNTIME_CODEHASH);
        bytes memory payload = abi.encodeCall(
            IProgrammableUniversalLaunchPreflightV1.closedRuntimeBindingHashV1,
            (account, expectedRuntimeCodeHash, expectedRuntimeBindingHash, requireStateless)
        );
        bool success;
        uint256 returnedSize;
        address preflight = _PREFLIGHT;
        assembly ("memory-safe") {
            success := staticcall(8000000, preflight, add(payload, 32), mload(payload), 0, 0)
            returnedSize := returndatasize()
            if and(success, eq(returnedSize, 32)) {
                returndatacopy(0, 0, 32)
                attestationHash := mload(0)
            }
        }
        if (!success || returnedSize != 32 || attestationHash == bytes32(0)) revert InvalidState();
        _requireRuntime(_PREFLIGHT, _PREFLIGHT_RUNTIME_CODEHASH);
    }

    function _requireControlEquality(ProfileDescriptorV1 calldata descriptor) private view {
        if (
            descriptor.securityControlHeadHash != _control.securityControlHeadHash
                || descriptor.securityEpoch != _control.securityEpoch
                || descriptor.securityEpochHash != _control.securityEpochHash
                || descriptor.policyEpoch != _control.policyEpoch
                || descriptor.policyEpochHash != _control.policyEpochHash
                || descriptor.reviewGeneration != _control.reviewGeneration
                || descriptor.reviewGenerationHash != _control.reviewGenerationHash
        ) revert InvalidState();
    }

    function _requireControlEquality(ProfileDescriptorV1 storage descriptor) private view {
        if (
            descriptor.securityControlHeadHash != _control.securityControlHeadHash
                || descriptor.securityEpoch != _control.securityEpoch
                || descriptor.securityEpochHash != _control.securityEpochHash
                || descriptor.policyEpoch != _control.policyEpoch
                || descriptor.policyEpochHash != _control.policyEpochHash
                || descriptor.reviewGeneration != _control.reviewGeneration
                || descriptor.reviewGenerationHash != _control.reviewGenerationHash
        ) revert InvalidState();
    }

    function _requireGrantControlEquality(LaunchGrantV1 calldata grant) private view {
        if (
            grant.securityControlHeadHash != _control.securityControlHeadHash
                || grant.securityEpoch != _control.securityEpoch
                || grant.securityEpochHash != _control.securityEpochHash || grant.policyEpoch != _control.policyEpoch
                || grant.policyEpochHash != _control.policyEpochHash
                || grant.reviewGeneration != _control.reviewGeneration
                || grant.reviewGenerationHash != _control.reviewGenerationHash
        ) revert InvalidState();
    }

    function _requireCurrentnessControlEquality(ExecutionCurrentnessV1 calldata currentness) private view {
        if (
            currentness.securityControlHeadHash != _control.securityControlHeadHash
                || currentness.securityEpoch != _control.securityEpoch
                || currentness.securityEpochHash != _control.securityEpochHash
                || currentness.policyEpoch != _control.policyEpoch
                || currentness.policyEpochHash != _control.policyEpochHash
                || currentness.reviewGeneration != _control.reviewGeneration
                || currentness.reviewGenerationHash != _control.reviewGenerationHash
        ) revert InvalidState();
    }

    function _validateControl(ControlStateV1 memory control) private pure {
        if (
            control.securityControlHeadHash == bytes32(0) || control.securityEpoch == 0
                || control.securityEpochHash == bytes32(0) || control.policyEpoch == 0
                || control.policyEpochHash == bytes32(0) || control.reviewGeneration == 0
                || control.reviewGenerationHash == bytes32(0)
        ) revert InvalidField(6);
    }

    function _requireRuntime(address account, bytes32 expectedCodeHash) private view {
        if (account == address(0) || expectedCodeHash == bytes32(0) || account.code.length == 0) {
            revert RuntimeCodeHashDrift(account);
        }
        if (account.codehash != expectedCodeHash) revert RuntimeCodeHashDrift(account);
    }

    function _requireSignature(address signer, bytes32 expectedCodeHash, bytes32 digest, bytes calldata signature)
        private
        view
    {
        if (signature.length == 0 || signature.length > MAX_SIGNATURE_BYTES) revert SignatureTooLarge();
        _requireRuntime(signer, expectedCodeHash);
        bytes memory payload = abi.encodeWithSelector(ERC1271_MAGIC_VALUE, digest, signature);
        bool success;
        uint256 returnedSize;
        bytes32 returnedWord;
        assembly ("memory-safe") {
            success := staticcall(100000, signer, add(payload, 32), mload(payload), 0, 0)
            returnedSize := returndatasize()
            if and(success, eq(returnedSize, 32)) {
                returndatacopy(0, 0, 32)
                returnedWord := mload(0)
            }
        }
        if (!success || returnedSize != 32 || returnedWord != bytes32(ERC1271_MAGIC_VALUE)) {
            revert SignatureRejected();
        }
    }

    function _requireWalletSignature(address wallet, bytes32 digest, bytes calldata signature) private view {
        if (wallet.code.length != 0) {
            _requireSignature(wallet, wallet.codehash, digest, signature);
            return;
        }
        if (signature.length != 65) revert SignatureRejected();
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly ("memory-safe") {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }
        if (
            v < 27 || v > 28 || uint256(s) > 0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0
                || ecrecover(digest, v, r, s) != wallet
        ) revert SignatureRejected();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {
    IProgrammableRuntimeBindingV1,
    IProgrammableUniversalLaunchKernelV1
} from "./IProgrammableUniversalLaunchKernelV1.sol";
import { IProgrammableUniversalLaunchPreflightV1 } from "./IProgrammableUniversalLaunchPreflightV1.sol";

/// @notice Side-effect-free typed readiness/currentness readback for the universal launch kernel.
/// @dev Provider quorum and simulation evidence remain reviewer-authenticated offchain commitments. This contract
///      recomputes only state that is synchronously observable on the execution chain.
contract ProgrammableUniversalLaunchPreflightV1 is IProgrammableUniversalLaunchPreflightV1 {
    uint16 private constant MASK_KERNEL = 1 << 0;
    uint16 private constant MASK_PROFILE = 1 << 1;
    uint16 private constant MASK_CONTROL_GRANT = 1 << 2;
    uint16 private constant MASK_WINNER = 1 << 3;
    uint16 private constant MASK_RESERVATIONS = 1 << 4;
    uint16 private constant MASK_RECEIPT = 1 << 5;
    uint16 private constant REQUIRED_ATOMIC_MASK =
        MASK_KERNEL | MASK_PROFILE | MASK_CONTROL_GRANT | MASK_WINNER | MASK_RESERVATIONS | MASK_RECEIPT;

    bytes32 private constant RUNTIME_HEAD_TYPEHASH = keccak256(
        "PreflightRuntimeHeadV1(uint256 chainId,address kernel,bytes32 kernelRuntimeCodeHash,bytes32 profileKey,uint8 profileStatus,address profileModule,bytes32 expectedProfileModuleRuntimeCodeHash,bytes32 actualProfileModuleRuntimeCodeHash)"
    );
    bytes32 private constant CONTROL_HEAD_TYPEHASH = keccak256(
        "PreflightControlHeadV1(bytes32 securityControlHeadHash,uint64 securityEpoch,bytes32 securityEpochHash,uint64 policyEpoch,bytes32 policyEpochHash,uint64 reviewGeneration,bytes32 reviewGenerationHash,bool globalKilled)"
    );
    bytes32 private constant LIFECYCLE_HEAD_TYPEHASH = keccak256(
        "PreflightLifecycleHeadV1(uint8 grantStatus,bytes32 grantHash,bytes32 winnerKeyHash,bytes32 grantStateHeadHash,bytes32 winnerNonceOccupant,bytes32 winnerKeyOccupant,bytes32 activeExecutionGrantDigest,uint8 receiptStatus,bytes32 receiptCoreHash,bytes32 finalityIndexingReceiptHash)"
    );
    bytes32 private constant RESERVATION_STATE_LEAF_TYPEHASH = keccak256(
        "PreflightReservationStateLeafV1(bytes32 reservationKey,uint8 scope,bytes32 exclusiveGrantDigest,bytes32 storedSharedIdentityHash,bytes32 expectedSharedIdentityHash,bytes32 expectedRuntimeCodeHash,bytes32 actualRuntimeCodeHash,bytes32 expectedManagerRuntimeCodeHash,bytes32 actualManagerRuntimeCodeHash)"
    );
    bytes32 private constant PREFLIGHT_READBACK_TYPEHASH = keccak256(
        "UniversalLaunchPreflightReadbackV1(bytes32 runtimeHeadHash,bytes32 controlHeadHash,bytes32 lifecycleHeadHash,bytes32 reservationSetHash,bytes32 reservationStateHash)"
    );
    bytes32 private constant CLOSED_RUNTIME_BINDING_TYPEHASH = keccak256(
        "ClosedRuntimeBindingV1(uint256 chainId,address account,bytes32 runtimeCodeHash,bytes32 runtimeBindingHash,bool stateless)"
    );

    error AtomicPreflightUnavailable(uint16 readinessMask);
    error ClosedRuntimeRequired(address account);

    function readbackV1(
        address kernel,
        bytes32 expectedKernelRuntimeCodeHash,
        bytes32 grantDigest,
        IProgrammableUniversalLaunchKernelV1.ReservationV1[] calldata reservations,
        bytes32 candidateCurrentnessDigest
    ) external view returns (PreflightReadbackV1 memory readback) {
        return _readback(kernel, expectedKernelRuntimeCodeHash, grantDigest, reservations, candidateCurrentnessDigest);
    }

    function atomicPreflightHashV1(
        address kernel,
        bytes32 expectedKernelRuntimeCodeHash,
        bytes32 grantDigest,
        IProgrammableUniversalLaunchKernelV1.ReservationV1[] calldata reservations
    ) external view returns (bytes32 readbackHash) {
        PreflightReadbackV1 memory readback =
            _readback(kernel, expectedKernelRuntimeCodeHash, grantDigest, reservations, bytes32(0));
        if (readback.readinessMask != REQUIRED_ATOMIC_MASK) revert AtomicPreflightUnavailable(readback.readinessMask);
        return readback.readbackHash;
    }

    function closedRuntimeBindingHashV1(
        address account,
        bytes32 expectedRuntimeCodeHash,
        bytes32 expectedRuntimeBindingHash,
        bool requireStateless
    ) external view returns (bytes32 attestationHash) {
        if (
            account == address(0) || expectedRuntimeCodeHash == bytes32(0) || expectedRuntimeBindingHash == bytes32(0)
                || account.code.length == 0 || account.codehash != expectedRuntimeCodeHash
        ) revert ClosedRuntimeRequired(account);
        _rejectMutableDispatch(account, requireStateless);

        bytes memory payload = abi.encodeCall(IProgrammableRuntimeBindingV1.runtimeBindingHashV1, ());
        bool success;
        uint256 returnedSize;
        bytes32 actualRuntimeBindingHash;
        assembly ("memory-safe") {
            success := staticcall(100000, account, add(payload, 32), mload(payload), 0, 0)
            returnedSize := returndatasize()
            if and(success, eq(returnedSize, 32)) {
                returndatacopy(0, 0, 32)
                actualRuntimeBindingHash := mload(0)
            }
        }
        if (!success || returnedSize != 32 || actualRuntimeBindingHash != expectedRuntimeBindingHash) {
            revert ClosedRuntimeRequired(account);
        }
        attestationHash = keccak256(
            abi.encode(
                CLOSED_RUNTIME_BINDING_TYPEHASH,
                block.chainid,
                account,
                expectedRuntimeCodeHash,
                expectedRuntimeBindingHash,
                requireStateless
            )
        );
    }

    function _rejectMutableDispatch(address account, bool requireStateless) private view {
        bytes memory runtime = account.code;
        uint256 length = runtime.length;
        for (uint256 i; i < length;) {
            uint8 opcode = uint8(runtime[i]);
            // Solidity places embedded creation/runtime blobs after an INVALID data delimiter.
            // They are not executable through the reviewed dispatcher and must not be parsed as opcodes.
            if (opcode == 0xfe) break;
            if (
                opcode == 0xf2 || opcode == 0xf4 || opcode == 0xff
                    || (requireStateless && (opcode == 0x54 || opcode == 0x55))
            ) revert ClosedRuntimeRequired(account);
            unchecked {
                if (opcode >= 0x60 && opcode <= 0x7f) i += opcode - 0x5f;
                ++i;
            }
        }
    }

    function _readback(
        address kernelAddress,
        bytes32 expectedKernelRuntimeCodeHash,
        bytes32 grantDigest,
        IProgrammableUniversalLaunchKernelV1.ReservationV1[] calldata reservations,
        bytes32 candidateCurrentnessDigest
    ) private view returns (PreflightReadbackV1 memory readback) {
        IProgrammableUniversalLaunchKernelV1 kernel = IProgrammableUniversalLaunchKernelV1(kernelAddress);
        IProgrammableUniversalLaunchKernelV1.LaunchGrantV1 memory grant = kernel.launchGrantV1(grantDigest);
        IProgrammableUniversalLaunchKernelV1.ProfileDescriptorV1 memory profile =
            kernel.profileDescriptorV1(grant.profileKey);
        IProgrammableUniversalLaunchKernelV1.ControlStateV1 memory control = kernel.controlStateV1();
        IProgrammableUniversalLaunchKernelV1.LaunchGrantStateHeadV1 memory grantHead =
            kernel.launchGrantStateHeadV1(grantDigest);
        IProgrammableUniversalLaunchKernelV1.CanonicalLaunchReceiptV1 memory receipt =
            kernel.canonicalLaunchReceiptV1(grantDigest);

        readback.chainId = block.chainid;
        readback.kernel = kernelAddress;
        readback.kernelRuntimeCodeHash = kernelAddress.codehash;
        readback.profileKey = grant.profileKey;
        readback.profileStatus = profile.status;
        readback.profileModule = profile.module;
        readback.expectedProfileModuleRuntimeCodeHash = profile.moduleRuntimeCodeHash;
        readback.actualProfileModuleRuntimeCodeHash = profile.module.codehash;
        readback.control = control;
        readback.grantStateHead = grantHead;
        readback.winnerNonceOccupant = kernel.winnerByNonceV1(grant.antiReplayNonce);
        readback.winnerKeyOccupant = kernel.winnerByKeyV1(grantHead.winnerKeyHash);
        readback.activeExecutionGrantDigest = kernel.activeExecutionGrantDigestV1();
        readback.reservationSetHash = kernel.computeReservationSetHashV1(reservations);
        readback.receiptStatus = receipt.status;
        readback.receiptCoreHash = receipt.receiptCoreHash;
        readback.finalityIndexingReceiptHash = receipt.finalityIndexingReceiptHash;
        if (candidateCurrentnessDigest != bytes32(0)) {
            (readback.candidateCurrentnessUsed, readback.candidateCurrentnessRevoked) =
                kernel.currentnessStatusV1(candidateCurrentnessDigest);
        }

        if (
            kernelAddress.code.length != 0 && kernelAddress.codehash == expectedKernelRuntimeCodeHash
                && expectedKernelRuntimeCodeHash != bytes32(0)
        ) readback.readinessMask |= MASK_KERNEL;
        if (
            profile.status == IProgrammableUniversalLaunchKernelV1.ProfileStatus.Active
                && profile.module.code.length != 0 && profile.module.codehash == profile.moduleRuntimeCodeHash
        ) readback.readinessMask |= MASK_PROFILE;
        if (_controlAndGrantCurrent(profile, grant, grantHead, control)) readback.readinessMask |= MASK_CONTROL_GRANT;
        if (
            readback.winnerNonceOccupant == grantDigest && readback.winnerKeyOccupant == grantDigest
                && readback.activeExecutionGrantDigest == bytes32(0)
                && grantHead.winnerKeyHash == kernel.computeWinnerKeyHashV1(grant)
        ) readback.readinessMask |= MASK_WINNER;

        bool reservationsReady;
        (readback.reservationStateHash, reservationsReady) = _reservationState(kernel, grantDigest, reservations);
        if (reservationsReady) readback.readinessMask |= MASK_RESERVATIONS;
        if (
            receipt.status == IProgrammableUniversalLaunchKernelV1.ReceiptStatus.Prepared
                && receipt.grantDigest == grantDigest && receipt.stampLaunchId == grant.stampLaunchId
                && receipt.receiptCoreHash != bytes32(0) && receipt.finalityIndexingReceiptHash == bytes32(0)
        ) readback.readinessMask |= MASK_RECEIPT;

        bytes32 runtimeHeadHash = _hashRuntime(readback);
        bytes32 controlHeadHash = _hashControl(control);
        bytes32 lifecycleHeadHash = _hashLifecycle(readback);
        readback.readbackHash = keccak256(
            abi.encode(
                PREFLIGHT_READBACK_TYPEHASH,
                runtimeHeadHash,
                controlHeadHash,
                lifecycleHeadHash,
                readback.reservationSetHash,
                readback.reservationStateHash
            )
        );
    }

    function _controlAndGrantCurrent(
        IProgrammableUniversalLaunchKernelV1.ProfileDescriptorV1 memory profile,
        IProgrammableUniversalLaunchKernelV1.LaunchGrantV1 memory grant,
        IProgrammableUniversalLaunchKernelV1.LaunchGrantStateHeadV1 memory head,
        IProgrammableUniversalLaunchKernelV1.ControlStateV1 memory control
    ) private pure returns (bool) {
        return !control.globalKilled && head.status == IProgrammableUniversalLaunchKernelV1.LaunchGrantStatus.Active
            && grant.profileKey == profile.profileKey && grant.sourceLaunchId != bytes32(0)
            && grant.stampLaunchId != bytes32(0) && grant.antiReplayNonce != bytes32(0)
            && grant.sourceLaunchId != grant.stampLaunchId && grant.sourceLaunchId != grant.antiReplayNonce
            && grant.stampLaunchId != grant.antiReplayNonce
            && profile.securityControlHeadHash == control.securityControlHeadHash
            && grant.securityControlHeadHash == control.securityControlHeadHash
            && profile.securityEpoch == control.securityEpoch && grant.securityEpoch == control.securityEpoch
            && profile.securityEpochHash == control.securityEpochHash
            && grant.securityEpochHash == control.securityEpochHash && profile.policyEpoch == control.policyEpoch
            && grant.policyEpoch == control.policyEpoch && profile.policyEpochHash == control.policyEpochHash
            && grant.policyEpochHash == control.policyEpochHash && profile.reviewGeneration == control.reviewGeneration
            && grant.reviewGeneration == control.reviewGeneration
            && profile.reviewGenerationHash == control.reviewGenerationHash
            && grant.reviewGenerationHash == control.reviewGenerationHash;
    }

    function _reservationState(
        IProgrammableUniversalLaunchKernelV1 kernel,
        bytes32,
        IProgrammableUniversalLaunchKernelV1.ReservationV1[] calldata reservations
    ) private view returns (bytes32 stateHash, bool allReady) {
        allReady = reservations.length != 0;
        for (uint256 i; i < reservations.length; ++i) {
            IProgrammableUniversalLaunchKernelV1.ReservationV1 calldata reservation = reservations[i];
            (bytes32 key, bytes32 exclusiveOccupant, bytes32 sharedIdentity) =
                kernel.reservationOccupantsV1(reservation);
            bytes32 actualRuntimeCodeHash;
            bytes32 actualManagerRuntimeCodeHash;
            bool runtimeReady;
            if (reservation.kind == IProgrammableUniversalLaunchKernelV1.ReservationKind.Pool) {
                actualManagerRuntimeCodeHash = reservation.manager.codehash;
                runtimeReady = reservation.manager.code.length != 0
                    && actualManagerRuntimeCodeHash == reservation.expectedManagerRuntimeCodeHash;
            } else {
                actualRuntimeCodeHash = reservation.account.codehash;
                if (reservation.scope == IProgrammableUniversalLaunchKernelV1.ReservationScope.Exclusive) {
                    runtimeReady = reservation.account.code.length == 0;
                } else {
                    runtimeReady = reservation.account.code.length != 0
                        && actualRuntimeCodeHash == reservation.expectedRuntimeCodeHash;
                }
            }
            bool occupantReady;
            if (reservation.scope == IProgrammableUniversalLaunchKernelV1.ReservationScope.Exclusive) {
                occupantReady = exclusiveOccupant == bytes32(0) && sharedIdentity == bytes32(0);
            } else {
                occupantReady = exclusiveOccupant == bytes32(0)
                    && (sharedIdentity == bytes32(0) || sharedIdentity == reservation.sharedIdentityHash);
            }
            allReady = allReady && runtimeReady && occupantReady;
            bytes32 leaf = _reservationStateLeaf(
                reservation, key, exclusiveOccupant, sharedIdentity, actualRuntimeCodeHash, actualManagerRuntimeCodeHash
            );
            stateHash = keccak256(abi.encode(stateHash, i, leaf));
        }
    }

    function _hashControl(IProgrammableUniversalLaunchKernelV1.ControlStateV1 memory control)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                CONTROL_HEAD_TYPEHASH,
                control.securityControlHeadHash,
                control.securityEpoch,
                control.securityEpochHash,
                control.policyEpoch,
                control.policyEpochHash,
                control.reviewGeneration,
                control.reviewGenerationHash,
                control.globalKilled
            )
        );
    }

    function _reservationStateLeaf(
        IProgrammableUniversalLaunchKernelV1.ReservationV1 calldata reservation,
        bytes32 key,
        bytes32 exclusiveOccupant,
        bytes32 sharedIdentity,
        bytes32 actualRuntimeCodeHash,
        bytes32 actualManagerRuntimeCodeHash
    ) private pure returns (bytes32) {
        return keccak256(
            abi.encode(
                RESERVATION_STATE_LEAF_TYPEHASH,
                key,
                uint8(reservation.scope),
                exclusiveOccupant,
                sharedIdentity,
                reservation.sharedIdentityHash,
                reservation.expectedRuntimeCodeHash,
                actualRuntimeCodeHash,
                reservation.expectedManagerRuntimeCodeHash,
                actualManagerRuntimeCodeHash
            )
        );
    }

    function _hashRuntime(PreflightReadbackV1 memory readback) private pure returns (bytes32) {
        return keccak256(
            abi.encode(
                RUNTIME_HEAD_TYPEHASH,
                readback.chainId,
                readback.kernel,
                readback.kernelRuntimeCodeHash,
                readback.profileKey,
                uint8(readback.profileStatus),
                readback.profileModule,
                readback.expectedProfileModuleRuntimeCodeHash,
                readback.actualProfileModuleRuntimeCodeHash
            )
        );
    }

    function _hashLifecycle(PreflightReadbackV1 memory readback) private pure returns (bytes32) {
        return keccak256(
            abi.encode(
                LIFECYCLE_HEAD_TYPEHASH,
                uint8(readback.grantStateHead.status),
                readback.grantStateHead.grantHash,
                readback.grantStateHead.winnerKeyHash,
                readback.grantStateHead.stateHeadHash,
                readback.winnerNonceOccupant,
                readback.winnerKeyOccupant,
                readback.activeExecutionGrantDigest,
                uint8(readback.receiptStatus),
                readback.receiptCoreHash,
                readback.finalityIndexingReceiptHash
            )
        );
    }
}

src/router_vnext/ProgrammableNestedFacto.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {
    IProgrammableRuntimeBindingV1,
    IProgrammableUniversalLaunchKernelV1
} from "./IProgrammableUniversalLaunchKernelV1.sol";
import {
    IProgrammableNestedFactoryProfileV1,
    IProgrammableNestedFactoryProviderV1,
    IProgrammableNestedFactoryPostconditionVerifierV1
} from "./IProgrammableNestedFactoryProfileV1.sol";

/// @notice Reusable typed NESTED_FACTORY execution profile.
/// @dev Provider and verifier are immutable. Every external call has a fixed target, selector, gas bound and exact
///      return size. The same deployed profile accepts multiple reviewed applicant plans.
contract ProgrammableNestedFactoryProfileV1 is IProgrammableNestedFactoryProfileV1 {
    uint16 private constant PLAN_SCHEMA_VERSION = 1;
    uint256 private constant MAX_COMPONENTS = 16;
    uint256 private constant PROVIDER_RETURN_BYTES = 256;
    uint256 private constant VERIFIER_RETURN_BYTES = 128;

    bytes32 public constant ACTION_IDENTITY_TYPEHASH = keccak256(
        "NestedFactoryActionIdentityV1(bytes32 providerPlanId,bytes32 factorySalt,address applicantWallet,bytes32 sourceLaunchId,address poolManager,bytes32 poolManagerRuntimeCodeHash,bytes32 poolId,address tokenOwner,address hookOwner,address treasury)"
    );
    bytes32 public constant ACTION_ECONOMICS_TYPEHASH = keccak256(
        "NestedFactoryActionEconomicsV1(uint256 tokenSupply,uint256 nativeValue,bytes32 hookPermissionsHash,bytes32 configurationHash)"
    );
    bytes32 public constant ACTION_TYPEHASH =
        keccak256("NestedFactoryActionV1(bytes32 identityHash,bytes32 economicsHash)");
    bytes32 public constant COMPONENT_TYPEHASH = keccak256(
        "NestedFactoryComponentV1(uint8 role,uint8 scope,address account,bytes32 runtimeCodeHash,bytes32 creationProvenanceHash,bytes32 ownershipBindingHash,bytes32 configurationHash)"
    );
    bytes32 public constant SHARED_COMPONENT_IDENTITY_TYPEHASH = keccak256(
        "NestedFactorySharedComponentIdentityV1(uint8 role,address account,bytes32 runtimeCodeHash,bytes32 creationProvenanceHash,bytes32 ownershipBindingHash,bytes32 configurationHash)"
    );
    bytes32 public constant EXPECTED_STATE_TYPEHASH = keccak256(
        "NestedFactoryExpectedStateV1(bytes32 returnedIdentitiesHash,bytes32 architectureStateHash,bytes32 poolStateHash,bytes32 revenueStateHash,bytes32 valueFlowHash)"
    );
    bytes32 public constant NESTED_FACTORY_PLAN_TYPEHASH = keccak256(
        "NestedFactoryPlanV1(uint16 schemaVersion,bytes32 actionHash,bytes32 orderedComponentHeadHash,bytes32 componentGraphHash,bytes32 componentSetHash,bytes32 componentRuntimeSetHash,bytes32 expectedStateHash)"
    );
    bytes32 public constant PROVIDER_EXECUTION_ID_TYPEHASH = keccak256(
        "NestedFactoryProviderExecutionIdV1(bytes32 providerBindingHash,bytes32 executionKey,bytes32 grantDigest,bytes32 stampLaunchId,bytes32 antiReplayNonce,bytes32 actionHash,bytes32 orderedComponentHeadHash)"
    );
    bytes32 public constant POSTCONDITION_TYPEHASH = keccak256(
        "NestedFactoryPostconditionV1(bytes32 providerExecutionId,bytes32 architectureStateHash,bytes32 poolStateHash,bytes32 revenueStateHash,bytes32 valueFlowHash,bytes32 returnedIdentitiesHash)"
    );

    IProgrammableUniversalLaunchKernelV1 public immutable KERNEL;
    bytes32 public immutable KERNEL_RUNTIME_CODEHASH;
    address public immutable PROVIDER;
    bytes32 public immutable PROVIDER_RUNTIME_CODEHASH;
    address public immutable POSTCONDITION_VERIFIER;
    bytes32 public immutable POSTCONDITION_VERIFIER_RUNTIME_CODEHASH;
    bytes32 public immutable VERIFIER_BINDING_HASH;
    bytes32 public immutable PROFILE_KEY;
    bytes32 public immutable PROVIDER_BINDING_HASH;
    uint32 public immutable PROVIDER_GAS_LIMIT;
    uint32 public immutable VERIFIER_GAS_LIMIT;

    bytes32 private _activeGrantDigest;

    struct ExecutionCorrelationV1 {
        bytes32 grantDigest;
        bytes32 stampLaunchId;
        bytes32 antiReplayNonce;
        bytes32 executionKey;
        bytes32 reservationSetHash;
    }

    error InvalidField(uint256 field);
    error RuntimeCodeHashDrift(address account);
    error UnauthorizedApplicant();
    error ReentrantExecution();
    error ComponentCollision(address account);
    error ProviderCallFailed();
    error ProviderReturnMalformed();
    error VerifierCallFailed();
    error VerifierReturnMalformed();
    error PostconditionMismatch();
    error UnexpectedValueFlow();

    event NestedFactoryLaunchFinalized(
        bytes32 indexed grantDigest,
        bytes32 indexed stampLaunchId,
        bytes32 indexed receiptCoreHash,
        bytes32 providerExecutionId
    );

    constructor(
        IProgrammableUniversalLaunchKernelV1 kernel,
        bytes32 kernelRuntimeCodeHash,
        address provider,
        bytes32 providerRuntimeCodeHash,
        address postconditionVerifier,
        bytes32 postconditionVerifierRuntimeCodeHash,
        bytes32 verifierBindingHash,
        bytes32 profileKey,
        bytes32 providerBindingHash,
        uint32 providerGasLimit,
        uint32 verifierGasLimit
    ) {
        if (
            address(kernel) == address(0) || profileKey == bytes32(0) || providerBindingHash == bytes32(0)
                || verifierBindingHash == bytes32(0)
        ) {
            revert InvalidField(1);
        }
        if (providerGasLimit < 100_000 || verifierGasLimit < 50_000) revert InvalidField(2);
        _requireRuntime(address(kernel), kernelRuntimeCodeHash);
        _requireRuntime(provider, providerRuntimeCodeHash);
        _requireRuntime(postconditionVerifier, postconditionVerifierRuntimeCodeHash);
        kernel.assertClosedRuntimeBindingV1(provider, providerRuntimeCodeHash, providerBindingHash, true);
        kernel.assertClosedRuntimeBindingV1(
            postconditionVerifier, postconditionVerifierRuntimeCodeHash, verifierBindingHash, true
        );
        KERNEL = kernel;
        KERNEL_RUNTIME_CODEHASH = kernelRuntimeCodeHash;
        PROVIDER = provider;
        PROVIDER_RUNTIME_CODEHASH = providerRuntimeCodeHash;
        POSTCONDITION_VERIFIER = postconditionVerifier;
        POSTCONDITION_VERIFIER_RUNTIME_CODEHASH = postconditionVerifierRuntimeCodeHash;
        VERIFIER_BINDING_HASH = verifierBindingHash;
        PROFILE_KEY = profileKey;
        PROVIDER_BINDING_HASH = providerBindingHash;
        PROVIDER_GAS_LIMIT = providerGasLimit;
        VERIFIER_GAS_LIMIT = verifierGasLimit;
    }

    function launchNestedFactoryV1(
        bytes32 grantDigest,
        NestedFactoryPlanV1 calldata plan,
        LaunchTransportV1 calldata transport
    ) external payable returns (bytes32 receiptCoreHash) {
        if (_activeGrantDigest != bytes32(0)) revert ReentrantExecution();
        _requireRuntime(address(KERNEL), KERNEL_RUNTIME_CODEHASH);
        _requireBoundRuntime(PROVIDER, PROVIDER_RUNTIME_CODEHASH, PROVIDER_BINDING_HASH);
        _requireBoundRuntime(POSTCONDITION_VERIFIER, POSTCONDITION_VERIFIER_RUNTIME_CODEHASH, VERIFIER_BINDING_HASH);

        IProgrammableUniversalLaunchKernelV1.LaunchGrantV1 memory grant = KERNEL.launchGrantV1(grantDigest);
        if (msg.sender != grant.applicantWallet || plan.action.applicantWallet != msg.sender) {
            revert UnauthorizedApplicant();
        }
        _validatePlan(grantDigest, plan, grant);
        if (
            transport.currentness.profilePreflightReadbackHash == bytes32(0)
                || transport.currentness.profilePreflightReadbackHash != _profilePreflightHash(plan)
        ) revert PostconditionMismatch();
        if (msg.value != plan.action.nativeValue) revert UnexpectedValueFlow();
        uint256 balanceBefore = address(this).balance - msg.value;
        IProgrammableUniversalLaunchKernelV1.ReservationV1[] memory reservations = _buildReservations(plan);
        bytes32 reservationSetHash = KERNEL.computeReservationSetHashV1(reservations);

        _activeGrantDigest = grantDigest;
        IProgrammableUniversalLaunchKernelV1.ProfileExecutionEnvelopeV1 memory envelope =
            IProgrammableUniversalLaunchKernelV1.ProfileExecutionEnvelopeV1({
                currentness: transport.currentness,
                currentnessSignature: transport.currentnessSignature,
                walletIntent: transport.walletIntent,
                walletSignature: transport.walletSignature,
                reservations: reservations
            });
        bytes32 executionKey = KERNEL.beginProfileExecutionV1(grantDigest, envelope);
        ExecutionCorrelationV1 memory correlation = ExecutionCorrelationV1({
            grantDigest: grantDigest,
            stampLaunchId: grant.stampLaunchId,
            antiReplayNonce: grant.antiReplayNonce,
            executionKey: executionKey,
            reservationSetHash: reservationSetHash
        });
        bytes32 providerExecutionId;
        (receiptCoreHash, providerExecutionId) = _executeVerifyFinalize(plan, correlation, balanceBefore);
        _activeGrantDigest = bytes32(0);
        emit NestedFactoryLaunchFinalized(
            correlation.grantDigest, correlation.stampLaunchId, receiptCoreHash, providerExecutionId
        );
    }

    function computeNestedFactoryPlanHashV1(NestedFactoryPlanV1 calldata plan) external pure returns (bytes32) {
        return _hashPlan(plan);
    }

    function nestedFactoryReservationsV1(NestedFactoryPlanV1 calldata plan)
        external
        pure
        returns (IProgrammableUniversalLaunchKernelV1.ReservationV1[] memory reservations)
    {
        return _buildReservations(plan);
    }

    function computeNestedFactoryPreflightHashV1(NestedFactoryPlanV1 calldata plan) external view returns (bytes32) {
        return _profilePreflightHash(plan);
    }

    function runtimeBindingHashV1() external view returns (bytes32) {
        return PROVIDER_BINDING_HASH;
    }

    function _profilePreflightHash(NestedFactoryPlanV1 calldata plan) private view returns (bytes32 readbackHash) {
        _requireBoundRuntime(POSTCONDITION_VERIFIER, POSTCONDITION_VERIFIER_RUNTIME_CODEHASH, VERIFIER_BINDING_HASH);
        bytes memory payload = abi.encodeCall(
            IProgrammableNestedFactoryPostconditionVerifierV1.verifyNestedPreflightV1, (address(this), plan)
        );
        bool success;
        uint256 returnedSize;
        address verifier = POSTCONDITION_VERIFIER;
        uint256 gasLimit = VERIFIER_GAS_LIMIT;
        assembly ("memory-safe") {
            success := staticcall(gasLimit, verifier, add(payload, 32), mload(payload), 0, 0)
            returnedSize := returndatasize()
            if and(success, eq(returnedSize, 32)) {
                returndatacopy(0, 0, 32)
                readbackHash := mload(0)
            }
        }
        if (!success) revert VerifierCallFailed();
        if (returnedSize != 32 || readbackHash == bytes32(0)) revert VerifierReturnMalformed();
        _requireBoundRuntime(POSTCONDITION_VERIFIER, POSTCONDITION_VERIFIER_RUNTIME_CODEHASH, VERIFIER_BINDING_HASH);
    }

    function _executeVerifyFinalize(
        NestedFactoryPlanV1 calldata plan,
        ExecutionCorrelationV1 memory correlation,
        uint256 balanceBefore
    ) private returns (bytes32 receiptCoreHash, bytes32 providerExecutionId) {
        NestedFactoryResultV1 memory providerResult = _executeProvider(plan, correlation);
        NestedPostconditionResultV1 memory postconditions = _verifyPostconditions(plan, providerResult);
        if (address(this).balance != balanceBefore) revert UnexpectedValueFlow();
        receiptCoreHash = _finalizeLaunch(plan, correlation, providerResult, postconditions);
        providerExecutionId = providerResult.providerExecutionId;
    }

    function _finalizeLaunch(
        NestedFactoryPlanV1 calldata plan,
        ExecutionCorrelationV1 memory correlation,
        NestedFactoryResultV1 memory providerResult,
        NestedPostconditionResultV1 memory postconditions
    ) private returns (bytes32 receiptCoreHash) {
        bytes32 postconditionHash = keccak256(
            abi.encode(
                POSTCONDITION_TYPEHASH,
                providerResult.providerExecutionId,
                postconditions.architectureStateHash,
                postconditions.poolStateHash,
                postconditions.revenueStateHash,
                postconditions.valueFlowHash,
                providerResult.returnedIdentitiesHash
            )
        );
        IProgrammableUniversalLaunchKernelV1.ExecutionResultV1 memory executionResult;
        executionResult.grantDigest = correlation.grantDigest;
        executionResult.stampLaunchId = correlation.stampLaunchId;
        executionResult.planHash = _hashPlan(plan);
        executionResult.componentSetHash = plan.componentSetHash;
        executionResult.componentRuntimeSetHash = plan.componentRuntimeSetHash;
        executionResult.configurationHash = plan.action.configurationHash;
        executionResult.reservationSetHash = correlation.reservationSetHash;
        executionResult.providerResultHash = keccak256(abi.encode(providerResult));
        executionResult.postconditionHash = postconditionHash;
        executionResult.valueFlowHash = postconditions.valueFlowHash;
        executionResult.deploymentLineageHash = providerResult.providerExecutionId;
        return KERNEL.finalizeProfileExecutionV1(executionResult);
    }

    function _validatePlan(
        bytes32 grantDigest,
        NestedFactoryPlanV1 calldata plan,
        IProgrammableUniversalLaunchKernelV1.LaunchGrantV1 memory grant
    ) private view {
        if (
            plan.schemaVersion != PLAN_SCHEMA_VERSION || grantDigest == bytes32(0)
                || plan.action.providerPlanId == bytes32(0) || plan.action.factorySalt == bytes32(0)
                || plan.action.sourceLaunchId != grant.sourceLaunchId || grant.sourceLaunchId == grant.stampLaunchId
                || grant.sourceLaunchId == grant.antiReplayNonce || grant.stampLaunchId == grant.antiReplayNonce
                || plan.action.poolManager == address(0) || plan.action.poolManagerRuntimeCodeHash == bytes32(0)
                || plan.action.poolId == bytes32(0) || plan.action.tokenOwner == address(0)
                || plan.action.hookOwner == address(0) || plan.action.treasury == address(0)
                || plan.action.tokenSupply == 0 || plan.action.hookPermissionsHash == bytes32(0)
                || plan.action.configurationHash != grant.configurationHash
                || plan.componentGraphHash != grant.componentGraphHash
                || plan.componentRuntimeSetHash != grant.componentRuntimeSetHash
                || plan.expectedReturnedIdentitiesHash == bytes32(0) || plan.expectedArchitectureStateHash == bytes32(0)
                || plan.expectedPoolStateHash == bytes32(0) || plan.expectedRevenueStateHash == bytes32(0)
                || plan.expectedValueFlowHash == bytes32(0) || _hashPlan(plan) != grant.planHash
        ) revert InvalidField(3);
        IProgrammableUniversalLaunchKernelV1.ProfileDescriptorV1 memory descriptor =
            KERNEL.profileDescriptorV1(PROFILE_KEY);
        if (
            grant.profileKey != PROFILE_KEY || descriptor.module != address(this)
                || descriptor.moduleRuntimeCodeHash != address(this).codehash
                || descriptor.providerBindingHash != PROVIDER_BINDING_HASH
                || descriptor.actionTypeHash != NESTED_FACTORY_PLAN_TYPEHASH
                || descriptor.capabilitySemantics != IProgrammableUniversalLaunchKernelV1.CapabilitySemantics.Execute
        ) revert InvalidField(4);
        (bytes32 componentHead, bytes32 componentSetHash, bytes32 runtimeSetHash) = _componentHashes(plan.components);
        if (
            componentHead == bytes32(0) || componentSetHash != plan.componentSetHash
                || runtimeSetHash != plan.componentRuntimeSetHash
        ) revert InvalidField(5);
        _validateComponentPrestate(plan.components);
    }

    function _executeProvider(NestedFactoryPlanV1 calldata plan, ExecutionCorrelationV1 memory correlation)
        private
        returns (NestedFactoryResultV1 memory result)
    {
        _requireBoundRuntime(PROVIDER, PROVIDER_RUNTIME_CODEHASH, PROVIDER_BINDING_HASH);
        result = _callProvider(plan, correlation);
        _requireBoundRuntime(PROVIDER, PROVIDER_RUNTIME_CODEHASH, PROVIDER_BINDING_HASH);
        _validateProviderResult(plan, correlation, result);
        _validateComponentPoststate(plan.components);
    }

    function _callProvider(NestedFactoryPlanV1 calldata plan, ExecutionCorrelationV1 memory correlation)
        private
        returns (NestedFactoryResultV1 memory result)
    {
        bytes memory payload = abi.encodeCall(
            IProgrammableNestedFactoryProviderV1.executeNestedFactoryV1,
            (
                correlation.executionKey,
                correlation.grantDigest,
                correlation.stampLaunchId,
                correlation.antiReplayNonce,
                plan.action,
                plan.components
            )
        );
        bytes memory output = new bytes(PROVIDER_RETURN_BYTES);
        bool success;
        uint256 returnedSize;
        address provider = PROVIDER;
        uint256 value = plan.action.nativeValue;
        uint256 gasLimit = PROVIDER_GAS_LIMIT;
        assembly ("memory-safe") {
            success := call(gasLimit, provider, value, add(payload, 32), mload(payload), add(output, 32), 256)
            returnedSize := returndatasize()
        }
        if (!success) revert ProviderCallFailed();
        if (returnedSize != PROVIDER_RETURN_BYTES) revert ProviderReturnMalformed();
        result = abi.decode(output, (NestedFactoryResultV1));
    }

    function _validateProviderResult(
        NestedFactoryPlanV1 calldata plan,
        ExecutionCorrelationV1 memory correlation,
        NestedFactoryResultV1 memory result
    ) private view {
        (bytes32 componentHead,,) = _componentHashes(plan.components);
        bytes32 expectedExecutionId = _expectedProviderExecutionId(plan, correlation, componentHead);
        if (
            result.providerExecutionId != expectedExecutionId
                || result.configurationHash != plan.action.configurationHash
                || result.componentSetHash != plan.componentSetHash
                || result.componentRuntimeSetHash != plan.componentRuntimeSetHash
                || result.architectureStateHash != plan.expectedArchitectureStateHash
                || result.poolStateHash != plan.expectedPoolStateHash
                || result.supplyValueFlowHash != plan.expectedValueFlowHash
                || result.returnedIdentitiesHash != plan.expectedReturnedIdentitiesHash
        ) revert PostconditionMismatch();
    }

    function _verifyPostconditions(NestedFactoryPlanV1 calldata plan, NestedFactoryResultV1 memory providerResult)
        private
        view
        returns (NestedPostconditionResultV1 memory postconditions)
    {
        _requireBoundRuntime(POSTCONDITION_VERIFIER, POSTCONDITION_VERIFIER_RUNTIME_CODEHASH, VERIFIER_BINDING_HASH);
        bytes memory payload = abi.encodeCall(
            IProgrammableNestedFactoryPostconditionVerifierV1.verifyNestedPostconditionsV1,
            (address(this), plan, providerResult)
        );
        bytes memory output = new bytes(VERIFIER_RETURN_BYTES);
        bool success;
        uint256 returnedSize;
        address verifier = POSTCONDITION_VERIFIER;
        uint256 gasLimit = VERIFIER_GAS_LIMIT;
        assembly ("memory-safe") {
            success := staticcall(gasLimit, verifier, add(payload, 32), mload(payload), add(output, 32), 128)
            returnedSize := returndatasize()
        }
        if (!success) revert VerifierCallFailed();
        if (returnedSize != VERIFIER_RETURN_BYTES) revert VerifierReturnMalformed();
        _requireBoundRuntime(POSTCONDITION_VERIFIER, POSTCONDITION_VERIFIER_RUNTIME_CODEHASH, VERIFIER_BINDING_HASH);
        postconditions = abi.decode(output, (NestedPostconditionResultV1));
        if (
            postconditions.architectureStateHash != plan.expectedArchitectureStateHash
                || postconditions.poolStateHash != plan.expectedPoolStateHash
                || postconditions.revenueStateHash != plan.expectedRevenueStateHash
                || postconditions.valueFlowHash != plan.expectedValueFlowHash
                || postconditions.architectureStateHash != providerResult.architectureStateHash
                || postconditions.poolStateHash != providerResult.poolStateHash
        ) revert PostconditionMismatch();
    }

    function _expectedProviderExecutionId(
        NestedFactoryPlanV1 calldata plan,
        ExecutionCorrelationV1 memory correlation,
        bytes32 componentHead
    ) private view returns (bytes32) {
        return keccak256(
            abi.encode(
                PROVIDER_EXECUTION_ID_TYPEHASH,
                PROVIDER_BINDING_HASH,
                correlation.executionKey,
                correlation.grantDigest,
                correlation.stampLaunchId,
                correlation.antiReplayNonce,
                _hashAction(plan.action),
                componentHead
            )
        );
    }

    function _validateComponentPrestate(ComponentExpectationV1[] calldata components) private view {
        uint256 length = components.length;
        if (length == 0 || length > MAX_COMPONENTS) revert InvalidField(6);
        for (uint256 i; i < length; ++i) {
            ComponentExpectationV1 calldata component = components[i];
            if (
                component.role == 0 || component.scope == ComponentScopeV1.None || component.account == address(0)
                    || component.runtimeCodeHash == bytes32(0) || component.creationProvenanceHash == bytes32(0)
                    || component.ownershipBindingHash == bytes32(0) || component.configurationHash == bytes32(0)
            ) revert InvalidField(7);
            for (uint256 j; j < i; ++j) {
                if (components[j].account == component.account) revert InvalidField(8);
            }
            if (component.scope == ComponentScopeV1.ExclusiveCreate) {
                if (component.account.code.length != 0) revert ComponentCollision(component.account);
            } else if (component.account.code.length == 0 || component.account.codehash != component.runtimeCodeHash) {
                revert RuntimeCodeHashDrift(component.account);
            }
        }
    }

    function _validateComponentPoststate(ComponentExpectationV1[] calldata components) private view {
        uint256 length = components.length;
        for (uint256 i; i < length; ++i) {
            ComponentExpectationV1 calldata component = components[i];
            if (component.account.code.length == 0 || component.account.codehash != component.runtimeCodeHash) {
                revert RuntimeCodeHashDrift(component.account);
            }
        }
    }

    function _buildReservations(NestedFactoryPlanV1 calldata plan)
        private
        pure
        returns (IProgrammableUniversalLaunchKernelV1.ReservationV1[] memory reservations)
    {
        uint256 length = plan.components.length;
        reservations = new IProgrammableUniversalLaunchKernelV1.ReservationV1[](length + 2);
        address token;
        bytes32 tokenRuntimeCodeHash;
        for (uint256 i; i < length; ++i) {
            ComponentExpectationV1 calldata component = plan.components[i];
            bool shared = component.scope == ComponentScopeV1.SharedInfrastructure;
            bytes32 sharedIdentityHash;
            if (shared) {
                sharedIdentityHash = keccak256(
                    abi.encode(
                        SHARED_COMPONENT_IDENTITY_TYPEHASH,
                        component.role,
                        component.account,
                        component.runtimeCodeHash,
                        component.creationProvenanceHash,
                        component.ownershipBindingHash,
                        component.configurationHash
                    )
                );
            }
            reservations[i] = IProgrammableUniversalLaunchKernelV1.ReservationV1({
                kind: IProgrammableUniversalLaunchKernelV1.ReservationKind.Component,
                scope: shared
                    ? IProgrammableUniversalLaunchKernelV1.ReservationScope.SharedInfrastructure
                    : IProgrammableUniversalLaunchKernelV1.ReservationScope.Exclusive,
                account: component.account,
                manager: address(0),
                identifier: bytes32(0),
                expectedRuntimeCodeHash: component.runtimeCodeHash,
                expectedManagerRuntimeCodeHash: bytes32(0),
                sharedIdentityHash: sharedIdentityHash
            });
            if (component.role == 1) {
                if (token != address(0)) revert InvalidField(9);
                token = component.account;
                tokenRuntimeCodeHash = component.runtimeCodeHash;
            }
        }
        if (token == address(0)) revert InvalidField(10);
        reservations[length] = IProgrammableUniversalLaunchKernelV1.ReservationV1({
            kind: IProgrammableUniversalLaunchKernelV1.ReservationKind.Token,
            scope: IProgrammableUniversalLaunchKernelV1.ReservationScope.Exclusive,
            account: token,
            manager: address(0),
            identifier: bytes32(0),
            expectedRuntimeCodeHash: tokenRuntimeCodeHash,
            expectedManagerRuntimeCodeHash: bytes32(0),
            sharedIdentityHash: bytes32(0)
        });
        reservations[length + 1] = IProgrammableUniversalLaunchKernelV1.ReservationV1({
            kind: IProgrammableUniversalLaunchKernelV1.ReservationKind.Pool,
            scope: IProgrammableUniversalLaunchKernelV1.ReservationScope.Exclusive,
            account: address(0),
            manager: plan.action.poolManager,
            identifier: plan.action.poolId,
            expectedRuntimeCodeHash: bytes32(0),
            expectedManagerRuntimeCodeHash: plan.action.poolManagerRuntimeCodeHash,
            sharedIdentityHash: bytes32(0)
        });
    }

    function _hashPlan(NestedFactoryPlanV1 calldata plan) private pure returns (bytes32) {
        (bytes32 componentHead,,) = _componentHashes(plan.components);
        bytes32 expectedStateHash = keccak256(
            abi.encode(
                EXPECTED_STATE_TYPEHASH,
                plan.expectedReturnedIdentitiesHash,
                plan.expectedArchitectureStateHash,
                plan.expectedPoolStateHash,
                plan.expectedRevenueStateHash,
                plan.expectedValueFlowHash
            )
        );
        return keccak256(
            abi.encode(
                NESTED_FACTORY_PLAN_TYPEHASH,
                plan.schemaVersion,
                _hashAction(plan.action),
                componentHead,
                plan.componentGraphHash,
                plan.componentSetHash,
                plan.componentRuntimeSetHash,
                expectedStateHash
            )
        );
    }

    function _hashAction(NestedFactoryActionV1 calldata action) private pure returns (bytes32) {
        bytes32 identityHash = keccak256(
            abi.encode(
                ACTION_IDENTITY_TYPEHASH,
                action.providerPlanId,
                action.factorySalt,
                action.applicantWallet,
                action.sourceLaunchId,
                action.poolManager,
                action.poolManagerRuntimeCodeHash,
                action.poolId,
                action.tokenOwner,
                action.hookOwner,
                action.treasury
            )
        );
        bytes32 economicsHash = keccak256(
            abi.encode(
                ACTION_ECONOMICS_TYPEHASH,
                action.tokenSupply,
                action.nativeValue,
                action.hookPermissionsHash,
                action.configurationHash
            )
        );
        return keccak256(abi.encode(ACTION_TYPEHASH, identityHash, economicsHash));
    }

    function _componentHashes(ComponentExpectationV1[] calldata components)
        private
        pure
        returns (bytes32 orderedHead, bytes32 componentSetHash, bytes32 runtimeSetHash)
    {
        uint256 length = components.length;
        if (length == 0 || length > MAX_COMPONENTS) return (bytes32(0), bytes32(0), bytes32(0));
        for (uint256 i; i < length; ++i) {
            ComponentExpectationV1 calldata component = components[i];
            bytes32 leaf = keccak256(
                abi.encode(
                    COMPONENT_TYPEHASH,
                    component.role,
                    uint8(component.scope),
                    component.account,
                    component.runtimeCodeHash,
                    component.creationProvenanceHash,
                    component.ownershipBindingHash,
                    component.configurationHash
                )
            );
            orderedHead = keccak256(abi.encode(orderedHead, i, leaf));
            componentSetHash = keccak256(abi.encode(componentSetHash, i, component.role, component.account, leaf));
            runtimeSetHash = keccak256(
                abi.encode(runtimeSetHash, i, component.role, component.account, component.runtimeCodeHash)
            );
        }
    }

    function _requireRuntime(address account, bytes32 expectedCodeHash) private view {
        if (
            account == address(0) || expectedCodeHash == bytes32(0) || account.code.length == 0
                || account.codehash != expectedCodeHash
        ) revert RuntimeCodeHashDrift(account);
    }

    function _requireBoundRuntime(address account, bytes32 expectedCodeHash, bytes32 expectedBindingHash) private view {
        _requireRuntime(account, expectedCodeHash);
        bytes memory payload = abi.encodeCall(IProgrammableRuntimeBindingV1.runtimeBindingHashV1, ());
        bool success;
        uint256 returnedSize;
        bytes32 actualBindingHash;
        assembly ("memory-safe") {
            success := staticcall(100000, account, add(payload, 32), mload(payload), 0, 0)
            returnedSize := returndatasize()
            if and(success, eq(returnedSize, 32)) {
                returndatacopy(0, 0, 32)
                actualBindingHash := mload(0)
            }
        }
        if (!success || returnedSize != 32 || actualBindingHash != expectedBindingHash) {
            revert RuntimeCodeHashDrift(account);
        }
        _requireRuntime(account, expectedCodeHash);
    }
}
